const page = `<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>해바라기 모임 투표</title><style>*{box-sizing:border-box}body{margin:0;background:#faf8ef;color:#111;font-family:system-ui,sans-serif}main{max-width:620px;margin:auto;padding:24px 18px 60px}.top{display:flex;justify-content:space-between;align-items:center;font-weight:900;font-size:14px}.tag,.mark{background:#ffdb00;padding:4px 8px}.hero{padding:38px 0 22px}.eyebrow{color:#0649ed;font-size:12px;font-weight:900;letter-spacing:.15em}h1{font-size:clamp(42px,10vw,68px);line-height:1.08;letter-spacing:-.08em;margin:15px 0}p{color:#656565;line-height:1.6}.ranking{width:100%;background:#0649ed;color:white;border:0;border-radius:14px;padding:17px;font-size:18px;font-weight:900;box-shadow:0 5px #0734ad}.section{margin-top:34px}.section h2{font-size:25px;letter-spacing:-.06em;margin:0 0 7px}.sub{font-size:13px;color:#777;margin:0 0 13px}.card{background:white;border:1px solid #eae8de;border-radius:18px;padding:15px;box-shadow:0 6px 20px #1111}form{display:flex;gap:8px}input,select{flex:1;min-width:0;padding:12px;border:1px solid #ddd;border-radius:10px;background:white;font-size:16px}button{cursor:pointer;font-family:inherit}form button{background:#111;color:white;border:0;border-radius:10px;font-size:14px;font-weight:800;padding:0 18px}.item{display:flex;align-items:center;gap:10px;border-top:1px solid #eee;padding-top:12px;margin-top:12px}.name{flex:1;font-weight:800;overflow-wrap:anywhere}.vote{background:#edf3ff;color:#0649ed;border:1px solid #bcd0ff;border-radius:30px;padding:8px 13px;font-weight:900}.vote.on{background:#0649ed;color:white}.empty{text-align:center;padding:23px 0 12px;font-size:14px;color:#888}.empty strong{display:block;color:#666;margin-bottom:5px}.footer{text-align:center;color:#888;font-size:12px;margin-top:40px}.modal{display:none;position:fixed;inset:0;background:#0009;align-items:end;justify-content:center}.modal.open{display:flex}.sheet{width:min(100%,620px);background:#faf8ef;border-radius:24px 24px 0 0;padding:24px;max-height:85vh;overflow:auto}.close{float:right;background:#eee;border:0;border-radius:50%;width:36px;height:36px;font-size:20px}.row{display:flex;gap:12px;padding:10px 0;border-bottom:1px solid #eee}.row span{flex:1}.row b:first-child{color:#0649ed}#status{color:#b43e2a;font-size:13px;margin-top:12px}.top{justify-content:center;flex-direction:column;gap:12px;font-size:23px}.tag{font-size:clamp(24px,6vw,38px);padding:2px 15px;transform:rotate(-2deg);box-shadow:4px 4px #e0b900}.hero{text-align:center;padding:20px 0 24px;position:relative}.hero:before,.hero:after{position:absolute;font-size:50px;top:65px}.hero:before{content:'🌻';left:-10px;transform:rotate(-20deg)}.hero:after{content:'🌻';right:-10px;transform:rotate(20deg)}.eyebrow{letter-spacing:.2em;color:#111}.hero h1{font-size:clamp(48px,11vw,78px);font-weight:1000;line-height:1.12;text-shadow:1px 1px #111;margin:20px 0}.hero h1 .mark{box-shadow:8px 0 #ffdb00,-8px 0 #ffdb00}.hero p{font-weight:750;color:#333}.ranking{font-size:clamp(19px,5vw,25px);padding:20px;border:3px solid #0037d1;box-shadow:0 6px #b5bfd3}.section{margin-top:32px}.section h2{font-size:31px;font-weight:1000}.section h2 .mark{display:inline-block;transform:rotate(-2deg);padding:3px 13px;box-shadow:4px 3px #e9bd00}.sub{display:inline-block;margin:10px 0 13px;font-weight:800;color:#333;border-bottom:3px solid #0649ed}.card{border:2px solid #eee;border-radius:22px;padding:17px}.card form button{background:#0649ed;font-size:16px;border-radius:12px;min-width:78px}.item{border:1px solid #ececec;border-radius:13px;padding:13px;margin-top:10px}.empty{background:#fffdf5;border:1px dashed #e5d886;border-radius:12px;margin-top:14px;padding:22px 5px}.footer{font-weight:800;color:#0649ed}.date{font-size:21px}@media(max-width:400px){.hero:before,.hero:after{font-size:34px;top:86px}.hero h1{font-size:43px}}
.poster{width:100%;aspect-ratio:852 / 382;overflow:hidden;margin:0 0 8px}.poster img{display:block;width:100%;height:auto}main{padding-top:8px}</style><body><main><div class="poster"><img src="data:image/png;base64," alt="해바라기 모임, 12월 5일 토요일. 일단 모여! 우리 같이 정해요."></div><button class="ranking" id="ranking">🏆 &nbsp;현재 순위 보기 &nbsp; →</button><div id="status" role="status"></div><div id="sections"></div><div class="footer">🌻 좋은 사람들과 맛있는 거 먹으면 그게 계획이지!</div></main><div class="modal" id="modal"><div class="sheet" role="dialog" aria-modal="true" aria-label="현재 순위"><button class="close" id="close" aria-label="닫기">×</button><h2>🏆 현재 순위</h2><p>따봉이 많은 순서대로 보여드려요.</p><div id="ranks"></div></div></div><script>
const types=[['time','⏰','시간','언제 만날까요?'],['place','📍','장소','어디서 만날까요?'],['menu','🍴','메뉴','뭐 먹을까요?']];let items=[];let voter=localStorage.getItem('sunflower-voter');if(!voter){voter=crypto.randomUUID();localStorage.setItem('sunflower-voter',voter)}const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){document.querySelector('#sections').innerHTML=types.map(([key,icon,title,sub])=>{let list=items.filter(x=>x.category===key);let input=key==='time'?'<select required aria-label="시간 선택"><option value="">시간을 선택해 주세요</option>'+Array.from({length:48},(_,i)=>{let h=Math.floor(i/2),m=i%2?'30':'00',v=(h<12?'오전 ':'오후 ')+(h%12||12)+':'+m;return '<option>'+v+'</option>'}).join('')+'</select>':'<input required maxlength="60" aria-label="'+title+' 입력" placeholder="'+(key==='place'?'장소를 입력해 주세요':'먹고 싶은 메뉴를 입력해 주세요')+'">';return '<section class="section"><h2><span class="mark">'+icon+' '+title+'</span></h2><p class="sub">'+sub+'</p><div class="card"><form data-type="'+key+'">'+input+'<button>+ 추가</button></form>'+(list.length?list.map(x=>'<div class="item"><span class="name">'+esc(x.name)+'</span><button class="vote '+(x.voted?'on':'')+'" data-id="'+x.id+'" aria-pressed="'+!!x.voted+'">👍 '+x.votes+'</button></div>').join(''):'<div class="empty"><strong>아직 제안이 없어요!</strong>첫 번째 '+title+'을 추가해 주세요.</div>')+'</div></section>'}).join('')}
async function api(path,method='GET',data){let r=await fetch(path,{method,headers:{'content-type':'application/json','x-voter':voter},body:data?JSON.stringify(data):undefined});let j=await r.json();if(!r.ok)throw Error(j.error||'오류가 발생했어요');return j}async function load(){try{items=await api('/api/items');document.querySelector('#status').textContent='';render()}catch(e){document.querySelector('#status').textContent='투표 정보를 불러오지 못했어요. 잠시 후 다시 시도해 주세요.';render()}}document.addEventListener('submit',async e=>{if(!e.target.matches('form'))return;e.preventDefault();try{await api('/api/items','POST',{category:e.target.dataset.type,name:e.target.querySelector('input,select').value});await load()}catch(e){alert(e.message)}});document.addEventListener('click',async e=>{let b=e.target.closest('.vote');if(!b)return;b.disabled=true;try{await api('/api/vote','POST',{id:b.dataset.id});await load()}catch(e){alert(e.message);b.disabled=false}});document.querySelector('#ranking').onclick=()=>{document.querySelector('#ranks').innerHTML=types.map(([k,i,t])=>{let a=items.filter(x=>x.category===k).sort((a,b)=>b.votes-a.votes||a.name.localeCompare(b.name,'ko'));return '<h3>'+i+' '+t+'</h3>'+(a.length?a.map((x,n)=>'<div class="row"><b>'+(n+1)+'</b><span>'+esc(x.name)+'</span><b>👍 '+x.votes+'</b></div>').join(''):'<p>아직 제안이 없어요.</p>')}).join('');document.querySelector('#modal').classList.add('open');document.querySelector('#close').focus()};document.querySelector('#close').onclick=()=>{document.querySelector('#modal').classList.remove('open');document.querySelector('#ranking').focus()};document.querySelector('#modal').onclick=e=>{if(e.target.id==='modal')document.querySelector('#close').click()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('#modal').classList.contains('open'))document.querySelector('#close').click()});load();</script></body></html>`;
export default {async fetch(request,env){const url=new URL(request.url);if(!url.pathname.startsWith('/api/'))return new Response(page,{headers:{'content-type':'text/html; charset=utf-8'}});const reply=(x,status=200)=>Response.json(x,{status,headers:{'cache-control':'no-store'}});if(!env.DB)return reply({error:'데이터베이스가 연결되지 않았어요.'},503);const voter=request.headers.get('x-voter')||'';if(!/^[a-f0-9-]{36}$/i.test(voter))return reply({error:'잘못된 요청입니다.'},400);try{if(url.pathname==='/api/items'&&request.method==='GET'){let {results}=await env.DB.prepare('SELECT i.id,i.category,i.name,COUNT(v.voter) AS votes,MAX(CASE WHEN v.voter=? THEN 1 ELSE 0 END) AS voted FROM items i LEFT JOIN votes v ON v.item_id=i.id GROUP BY i.id ORDER BY i.created_at,i.id').bind(voter).all();return reply(results)}if(request.method!=='POST')return reply({error:'잘못된 요청입니다.'},405);let body=await request.json();if(url.pathname==='/api/items'){let name=String(body.name||'').trim(),category=body.category;if(!['time','place','menu'].includes(category)||!name||name.length>60)return reply({error:'내용을 확인해 주세요.'},400);if(category==='time'&&!/^(오전|오후) (1[0-2]|[1-9]):(00|30)$/.test(name))return reply({error:'시간을 선택해 주세요.'},400);let existing=await env.DB.prepare('SELECT id FROM items WHERE category=? AND name=? COLLATE NOCASE').bind(category,name).first();if(existing)return reply({error:'이미 추가된 제안이에요.'},409);await env.DB.prepare('INSERT INTO items (id,category,name,created_at) VALUES (?,?,?,?)').bind(crypto.randomUUID(),category,name,Date.now()).run();return reply({ok:true})}if(url.pathname==='/api/vote'){let id=String(body.id||'');let item=await env.DB.prepare('SELECT id FROM items WHERE id=?').bind(id).first();if(!item)return reply({error:'제안을 찾을 수 없어요.'},404);let vote=await env.DB.prepare('SELECT 1 FROM votes WHERE item_id=? AND voter=?').bind(id,voter).first();if(vote)await env.DB.prepare('DELETE FROM votes WHERE item_id=? AND voter=?').bind(id,voter).run();else await env.DB.prepare('INSERT OR IGNORE INTO votes (item_id,voter) VALUES (?,?)').bind(id,voter).run();return reply({ok:true})}return reply({error:'찾을 수 없어요.'},404)}catch(e){return reply({error:'처리하지 못했어요. 다시 시도해 주세요.'},500)}}};
